function CustomerInvestmentCategory({item}:{item:(typeof customerInvestmentNavigation)[number]}) { const Icon=item.icon; return <div className={`arb-page portal-page customer-investment-page customer-investment-${item.tone}`}><div className="portal-page-top"><div><div className="eyebrow">{item.kicker}</div><h1>{item.label}</h1><p>{item.description}</p></div><span className="admin-live-chip"><span className="pulse"/> Account-linked workspace</span></div><div className="customer-investment-hero"><div className={`customer-investment-icon ${item.tone}`}><Icon size={25}/></div><div><span className="eyebrow">Opportunity catalogue</span><h2>Review {item.label.toLowerCase()} opportunities</h2><p>Every opportunity will be shown with eligibility, risk, timing, expected terms, and the account action available to you before anything is requested.</p></div><button className="secondary-button" onClick={()=>window.scrollTo({top:document.body.scrollHeight,behavior:"smooth"})}>View review standards <ArrowDownToLine size={14}/></button></div><div className="customer-investment-grid"><div className="customer-investment-card"><span className="eyebrow">What you will see</span><h2>Clear information before action</h2><ul><li>Opportunity details and participation requirements</li><li>Duration, timeline, capacity, and account limits</li><li>Risk notes and provider or registry status</li><li>Review, compare, and support actions</li></ul></div><div className="customer-investment-card"><span className="eyebrow">Account protection</span><h2>Nothing is committed from this page</h2><p>Reviewing a category does not move wallet funds or create a ledger entry. Any future request will use a separate confirmation step with server-side eligibility and policy checks.</p><div className="test-notice"><ShieldCheck size={15}/><span>Database-backed customer controls remain authoritative.</span></div></div></div><div className="customer-investment-note"><CircleHelp size={16}/><span>Want help deciding where to start? Open <strong>Support centre</strong> from the main menu or Customer tools drawer.</span></div></div>; }

