function Insights({notify}:{notify:(a:string,b:string)=>void}) { const rows=[["BTC / USDC","0.82%","94.4%","$22.6k","Moderate"],["ETH / USDT","0.64%","88.1%","$14.2k","Moderate"],["SOL / USDC","1.11%","61.7%","$8.9k","Elevated"],["AVAX / USDC","0.47%","76.3%","$6.1k","Moderate"]]; return <div className="page arb-page"><PageIntro eyebrow="Research desk" title="Market insights" body="A deeper view of route quality, liquidity and the assumptions behind recorded opportunities." action="Refresh signals" onAction={()=>notify("Signals refreshed","All research panels use transaction process data in this prototype.")} /><div className="insight-kpis"><div><span>Routes scanned</span><strong>148</strong><b>+12 today</b></div><div><span>Median net spread</span><strong>0.58%</strong><b>+0.07%</b></div><div><span>Liquidity coverage</span><strong>82.4%</strong><b>Healthy</b></div><div><span>Data freshness</span><strong>1.8s</strong><b>Within target</b></div></div><div className="insights-layout"><div className="panel"><div className="panel-heading"><div><div className="eyebrow">Route quality matrix</div><h2>Where the signal is strongest</h2></div><SlidersHorizontal size={18}/></div><div className="insight-table"><div className="insight-head"><span>Route</span><span>Net spread</span><span>Fill confidence</span><span>Capacity</span><span>Risk</span></div>{rows.map((r)=><div className="insight-row" key={r[0]}><strong>{r[0]}</strong><b className="positive-text">{r[1]}</b><span><i className="confidence"><em style={{width:r[2]}}/></i>{r[2]}</span><span>{r[3]}</span><span className={`risk ${r[4].toLowerCase()}`}>{r[4]}</span></div>)}</div></div><div className="panel signal-panel"><div className="eyebrow">Signal health</div><h2>Stable with pockets of activity</h2><div className="signal-score"><strong>84</strong><span>/ 100</span></div><div className="score-bar"><i style={{width:"84%"}}/></div><div className="signal-list"><span><i className="mint-dot"/>Venue availability <b>96%</b></span><span><i className="blue-dot"/>Quote agreement <b>88%</b></span><span><i className="amber-dot"/>Network confidence <b>71%</b></span></div></div></div></div>; }
